for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/qwenaudio/cosyvoice","slug":"cosyvoice-53c7af90","name":"CosyVoice","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tạo voice có chỉ dẫn về cảm xúc, tốc độ và cách phát âm.","description":"CosyVoice là họ TTS có zero-shot voice cloning, streaming và điều khiển bằng chỉ dẫn. README hiện giới thiệu Fun-CosyVoice 3.0; khả năng và cấu hình của 1.0/2.0/3.0 cần được phân biệt khi chọn cho video kit.","long_description":"ĐIỂM NỔI BẬT\n• Hỗ trợ giữ đặc trưng giọng qua nhiều ngôn ngữ được liệt kê.\n• Có chỉ dẫn cảm xúc, tốc độ, âm lượng và streaming đầu vào/đầu ra.\n• Có chỉnh phát âm Pinyin/âm vị tiếng Anh và xử lý số/ký hiệu.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử voice tiếng Anh cho bản demo sản phẩm, điều chỉnh cách đọc tên và nhịp trước khi tạo timestamp.\n\nBẮT ĐẦU\nChọn phiên bản model, môi trường và ví dụ chính chủ tương ứng; chỉ tải trọng số thực sự cần.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nDanh sách 9 ngôn ngữ của 3.0 chưa có tiếng Việt. Độ trễ công bố không bảo đảm trên mọi máy; clone giọng phải được phép và kiểm tra giấy phép model.","canonical_url":"https://github.com/QwenAudio/CosyVoice","repository_url":"https://github.com/QwenAudio/CosyVoice","documentation_url":"https://raw.githubusercontent.com/QwenAudio/CosyVoice/main/README.md","owner_name":"QwenAudio","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":51,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Tạo voice có chỉ dẫn về cảm xúc, tốc độ và cách phát âm. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tạo voice có chỉ dẫn về cảm xúc, tốc độ và cách phát âm.","highlights":["Hỗ trợ giữ đặc trưng giọng qua nhiều ngôn ngữ được liệt kê.","Có chỉ dẫn cảm xúc, tốc độ, âm lượng và streaming đầu vào/đầu ra.","Có chỉnh phát âm Pinyin/âm vị tiếng Anh và xử lý số/ký hiệu."],"example":"Thử voice tiếng Anh cho bản demo sản phẩm, điều chỉnh cách đọc tên và nhịp trước khi tạo timestamp.","setup":"Chọn phiên bản model, môi trường và ví dụ chính chủ tương ứng; chỉ tải trọng số thực sự cần.","limitations":"Danh sách 9 ngôn ngữ của 3.0 chưa có tiếng Việt. Độ trễ công bố không bảo đảm trên mọi máy; clone giọng phải được phép và kiểm tra giấy phép model.","github":{"stars":23441,"forks":2669,"observedAt":"2026-09-03T16:12:45.725Z","url":"https://github.com/QwenAudio/CosyVoice","pushedAt":"2026-05-25T18:15:40Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/QwenAudio/CosyVoice/main/README.md","observedAt":"2026-09-03T16:13:02.233Z","sha256":"66436370172c2830ed98aa643b31898c65e16eee14ade68f00828d21fae602e0"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"QwenAudio/CosyVoice:metadata","source_url":"https://github.com/QwenAudio/CosyVoice","raw_metadata":{"metadataUrl":"https://api.github.com/repositories/823430322","stars":23441,"forks":2669,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:12:45.725Z"},{"source_type":"github","source_identifier":"QwenAudio/CosyVoice:readme:66436370172c2830ed98aa643b31898c65e16eee14ade68f00828d21fae602e0","source_url":"https://raw.githubusercontent.com/QwenAudio/CosyVoice/main/README.md","raw_metadata":{"sha256":"66436370172c2830ed98aa643b31898c65e16eee14ade68f00828d21fae602e0","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:13:02.233Z"}],"expected":null},{"identity":"repo:https://github.com/audacity/audacity","slug":"audacity-4158f7cd","name":"Audacity","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Thu và chỉnh nhiều track âm thanh trước khi dựng video.","description":"Audacity là trình thu và biên tập audio đa track trên Windows, macOS và Linux. Đây là công cụ nền cho creator tự thu lời đọc và chuẩn bị âm thanh, không cần biến mọi khâu thành AI. README hiện lưu ý nhánh master đang chuyển lớn sang Audacity 4.","long_description":"ĐIỂM NỔI BẬT\n• Ghi và biên tập audio nhiều track.\n• Có bản desktop đa nền tảng và hệ tài liệu chính chủ.\n• Tách hướng phát triển Audacity 4 khỏi dòng 3.x.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThu vài lượt lời đọc, chọn phần tốt và ghép thành bản voice sạch trước khi căn phụ đề.\n\nBẮT ĐẦU\nDùng bản phát hành ổn định từ website; không tự lấy nhánh master đang tái cấu trúc cho dự án cần giao.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCần kiểm tra mức thu và đầu vào micro; phần mềm không tự giải quyết phòng thu ồn. Plugin và dịch vụ bổ sung có thể có điều kiện riêng.","canonical_url":"https://github.com/audacity/audacity","repository_url":"https://github.com/audacity/audacity","documentation_url":"https://raw.githubusercontent.com/audacity/audacity/master/README.md","owner_name":"audacity","license":"GPLv3 cho phần mềm theo README; có mã và phụ thuộc mang điều khoản riêng.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":52,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Thu và chỉnh nhiều track âm thanh trước khi dựng video. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Thu và chỉnh nhiều track âm thanh trước khi dựng video.","highlights":["Ghi và biên tập audio nhiều track.","Có bản desktop đa nền tảng và hệ tài liệu chính chủ.","Tách hướng phát triển Audacity 4 khỏi dòng 3.x."],"example":"Thu vài lượt lời đọc, chọn phần tốt và ghép thành bản voice sạch trước khi căn phụ đề.","setup":"Dùng bản phát hành ổn định từ website; không tự lấy nhánh master đang tái cấu trúc cho dự án cần giao.","limitations":"Cần kiểm tra mức thu và đầu vào micro; phần mềm không tự giải quyết phòng thu ồn. Plugin và dịch vụ bổ sung có thể có điều kiện riêng.","github":{"stars":17885,"forks":2629,"observedAt":"2026-09-03T16:08:48.098Z","url":"https://github.com/audacity/audacity","pushedAt":"2026-09-03T14:16:02Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/audacity/audacity/master/README.md","observedAt":"2026-09-03T16:10:27.838Z","sha256":"c84ab5991133706a2899c20539df624ecaa124b7be9d4aff6d2b20986978d121"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"audacity/audacity:metadata","source_url":"https://github.com/audacity/audacity","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aace-step%2FACE-Step-1.5%20repo%3Afacebookresearch%2Faudiocraft%20repo%3AAnjok07%2Fultimatevocalremovergui%20repo%3Aaudacity%2Faudacity%20repo%3AComfy-Org%2FComfyUI%20repo%3AAUTOMATIC1111%2Fstable-diffusion-webui%20repo%3Alllyasviel%2FFooocus%20repo%3Ainvoke-ai%2FInvokeAI&per_page=100","stars":17885,"forks":2629,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:08:48.098Z"},{"source_type":"github","source_identifier":"audacity/audacity:readme:c84ab5991133706a2899c20539df624ecaa124b7be9d4aff6d2b20986978d121","source_url":"https://raw.githubusercontent.com/audacity/audacity/master/README.md","raw_metadata":{"sha256":"c84ab5991133706a2899c20539df624ecaa124b7be9d4aff6d2b20986978d121","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:27.838Z"}],"expected":null},{"identity":"repo:https://github.com/swivid/f5-tts","slug":"f5-tts-869687b2","name":"F5-TTS","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tạo lời đọc theo mẫu giọng, với một lưu ý giấy phép rất quan trọng.","description":"F5-TTS là hệ tổng hợp giọng nói có giao diện Gradio, CLI và các lựa chọn suy luận/tinh chỉnh. Nó đáng thử để nghiên cứu voice theo phong cách, nhiều người nói hoặc chia đoạn, nhưng trọng số chính chủ không có cùng quyền sử dụng như mã nguồn MIT.","long_description":"ĐIỂM NỔI BẬT\n• Có TTS chia đoạn và tạo nhiều phong cách/người nói.\n• Giao diện web và đường dùng trong script.\n• Tài liệu cấu hình cho NVIDIA, AMD, Intel và Apple Silicon.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử lời đọc ngắn bằng giọng đã được cho phép trong dự án nghiên cứu phi thương mại.\n\nBẮT ĐẦU\nTạo môi trường riêng, cài PyTorch phù hợp thiết bị, FFmpeg và chọn trọng số có điều kiện rõ ràng.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nTrọng số pretrained được README ghi CC-BY-NC: không mặc định dùng cho kênh kiếm tiền. Khả năng ngôn ngữ tùy checkpoint; clone giọng cần sự đồng ý.","canonical_url":"https://github.com/SWivid/F5-TTS","repository_url":"https://github.com/SWivid/F5-TTS","documentation_url":"https://raw.githubusercontent.com/SWivid/F5-TTS/main/README.md","owner_name":"SWivid","license":"Code MIT; trọng số pretrained CC-BY-NC theo README, không dùng thương mại mặc định.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":53,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Tạo lời đọc theo mẫu giọng, với một lưu ý giấy phép rất quan trọng. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tạo lời đọc theo mẫu giọng, với một lưu ý giấy phép rất quan trọng.","highlights":["Có TTS chia đoạn và tạo nhiều phong cách/người nói.","Giao diện web và đường dùng trong script.","Tài liệu cấu hình cho NVIDIA, AMD, Intel và Apple Silicon."],"example":"Thử lời đọc ngắn bằng giọng đã được cho phép trong dự án nghiên cứu phi thương mại.","setup":"Tạo môi trường riêng, cài PyTorch phù hợp thiết bị, FFmpeg và chọn trọng số có điều kiện rõ ràng.","limitations":"Trọng số pretrained được README ghi CC-BY-NC: không mặc định dùng cho kênh kiếm tiền. Khả năng ngôn ngữ tùy checkpoint; clone giọng cần sự đồng ý.","github":{"stars":15189,"forks":2206,"observedAt":"2026-09-03T16:08:35.124Z","url":"https://github.com/SWivid/F5-TTS","pushedAt":"2026-07-23T09:20:37Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/SWivid/F5-TTS/main/README.md","observedAt":"2026-09-03T16:10:14.207Z","sha256":"3c74da9760857de03a0fe22d6124fd50000b986c6aeba6c23bb14635e20e4ae1"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"SWivid/F5-TTS:metadata","source_url":"https://github.com/SWivid/F5-TTS","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3ABlaizzy%2Fmlx-video%20repo%3Aopenai%2Fwhisper%20repo%3Am-bain%2FwhisperX%20repo%3ASYSTRAN%2Ffaster-whisper%20repo%3Aggml-org%2Fwhisper.cpp%20repo%3AFunAudioLLM%2FCosyVoice%20repo%3ASWivid%2FF5-TTS%20repo%3Ahexgrad%2Fkokoro&per_page=100","stars":15189,"forks":2206,"license":"MIT"},"fetched_at":"2026-09-03T16:08:35.124Z"},{"source_type":"github","source_identifier":"SWivid/F5-TTS:readme:3c74da9760857de03a0fe22d6124fd50000b986c6aeba6c23bb14635e20e4ae1","source_url":"https://raw.githubusercontent.com/SWivid/F5-TTS/main/README.md","raw_metadata":{"sha256":"3c74da9760857de03a0fe22d6124fd50000b986c6aeba6c23bb14635e20e4ae1","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:14.207Z"}],"expected":null},{"identity":"repo:https://github.com/ace-step/ace-step-1.5","slug":"ace-step-1-5-ae8ddda5","name":"ACE-Step 1.5","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tạo nhạc theo mood, tempo và độ dài, rồi chỉnh lại từng phần.","description":"ACE-Step 1.5 là hệ tạo nhạc có giao diện và API, kết hợp mô tả, lời, metadata và audio tham chiếu. Ngoài sinh mới, README liệt kê sửa vùng, tách track và thêm lớp. Đây là ứng viên thử soundtrack nguyên bản, không phải bảo đảm không có tranh chấp bản quyền.","long_description":"ĐIỂM NỔI BẬT\n• Điều khiển độ dài, BPM, key và cấu trúc/lời.\n• Có repaint, tham chiếu audio, tách stem và thêm layer.\n• Có Gradio, API và các biến thể model theo tài nguyên.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTạo một đoạn nhạc nền không lời theo mood của series, nghe so với voice và sửa phần quá nổi.\n\nBẮT ĐẦU\nTheo hướng dẫn đúng bản base/XL; chuẩn bị Python và phần cứng, tính dung lượng tải model.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nBản XL yêu cầu cao hơn bản nhẹ: README nêu tối thiểu 12GB VRAM với offload. Không sao chép tác phẩm/giọng không được phép; thông số tốc độ là tác giả đo, chưa được Windi kiểm thử.","canonical_url":"https://github.com/ace-step/ACE-Step-1.5","repository_url":"https://github.com/ace-step/ACE-Step-1.5","documentation_url":"https://raw.githubusercontent.com/ace-step/ACE-Step-1.5/main/README.md","owner_name":"ace-step","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":54,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Tạo nhạc theo mood, tempo và độ dài, rồi chỉnh lại từng phần. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tạo nhạc theo mood, tempo và độ dài, rồi chỉnh lại từng phần.","highlights":["Điều khiển độ dài, BPM, key và cấu trúc/lời.","Có repaint, tham chiếu audio, tách stem và thêm layer.","Có Gradio, API và các biến thể model theo tài nguyên."],"example":"Tạo một đoạn nhạc nền không lời theo mood của series, nghe so với voice và sửa phần quá nổi.","setup":"Theo hướng dẫn đúng bản base/XL; chuẩn bị Python và phần cứng, tính dung lượng tải model.","limitations":"Bản XL yêu cầu cao hơn bản nhẹ: README nêu tối thiểu 12GB VRAM với offload. Không sao chép tác phẩm/giọng không được phép; thông số tốc độ là tác giả đo, chưa được Windi kiểm thử.","github":{"stars":12528,"forks":1598,"observedAt":"2026-09-03T16:08:48.098Z","url":"https://github.com/ace-step/ACE-Step-1.5","pushedAt":"2026-09-03T02:46:44Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/ace-step/ACE-Step-1.5/main/README.md","observedAt":"2026-09-03T16:10:28.457Z","sha256":"650c6ef98b70289886669895c4fd68aab3cc45bba74b3525d728a45a85cbcd66"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"ace-step/ACE-Step-1.5:metadata","source_url":"https://github.com/ace-step/ACE-Step-1.5","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aace-step%2FACE-Step-1.5%20repo%3Afacebookresearch%2Faudiocraft%20repo%3AAnjok07%2Fultimatevocalremovergui%20repo%3Aaudacity%2Faudacity%20repo%3AComfy-Org%2FComfyUI%20repo%3AAUTOMATIC1111%2Fstable-diffusion-webui%20repo%3Alllyasviel%2FFooocus%20repo%3Ainvoke-ai%2FInvokeAI&per_page=100","stars":12528,"forks":1598,"license":"MIT"},"fetched_at":"2026-09-03T16:08:48.098Z"},{"source_type":"github","source_identifier":"ace-step/ACE-Step-1.5:readme:650c6ef98b70289886669895c4fd68aab3cc45bba74b3525d728a45a85cbcd66","source_url":"https://raw.githubusercontent.com/ace-step/ACE-Step-1.5/main/README.md","raw_metadata":{"sha256":"650c6ef98b70289886669895c4fd68aab3cc45bba74b3525d728a45a85cbcd66","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:28.457Z"}],"expected":null},{"identity":"repo:https://github.com/hexgrad/kokoro","slug":"kokoro-ff271a4f","name":"Kokoro","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một lựa chọn TTS gọn để thử voice cho kênh quốc tế.","description":"Kokoro là thư viện suy luận cho mô hình TTS 82 triệu tham số. Nó có ví dụ Python/Colab và lựa chọn giọng theo ngôn ngữ, phù hợp thử lời đọc mà không bắt đầu bằng một mô hình quá lớn. Danh sách ngôn ngữ trong README chưa có tiếng Việt.","long_description":"ĐIỂM NỔI BẬT\n• Pipeline tạo audio theo đoạn và lưu WAV.\n• Có lựa chọn tiếng Anh Mỹ/Anh cùng một số ngôn ngữ khác.\n• README nêu trọng số Apache và hướng dẫn Apple Silicon.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử hai giọng tiếng Anh cho kịch bản hướng dẫn, chọn cách đọc rồi căn phụ đề bằng công cụ ASR.\n\nBẮT ĐẦU\nĐọc ví dụ KPipeline, cài thư viện phát âm/phụ thuộc đúng ngôn ngữ và hệ điều hành.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông quảng cáo đọc tiếng Việt sẵn. Chất lượng tên riêng và từ ngoài từ điển cần nghe soát; gọn hơn không có nghĩa mọi máy đều tạo real-time.","canonical_url":"https://github.com/hexgrad/kokoro","repository_url":"https://github.com/hexgrad/kokoro","documentation_url":"https://raw.githubusercontent.com/hexgrad/kokoro/main/README.md","owner_name":"hexgrad","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":55,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Một lựa chọn TTS gọn để thử voice cho kênh quốc tế. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một lựa chọn TTS gọn để thử voice cho kênh quốc tế.","highlights":["Pipeline tạo audio theo đoạn và lưu WAV.","Có lựa chọn tiếng Anh Mỹ/Anh cùng một số ngôn ngữ khác.","README nêu trọng số Apache và hướng dẫn Apple Silicon."],"example":"Thử hai giọng tiếng Anh cho kịch bản hướng dẫn, chọn cách đọc rồi căn phụ đề bằng công cụ ASR.","setup":"Đọc ví dụ KPipeline, cài thư viện phát âm/phụ thuộc đúng ngôn ngữ và hệ điều hành.","limitations":"Không quảng cáo đọc tiếng Việt sẵn. Chất lượng tên riêng và từ ngoài từ điển cần nghe soát; gọn hơn không có nghĩa mọi máy đều tạo real-time.","github":{"stars":8674,"forks":948,"observedAt":"2026-09-03T16:08:35.124Z","url":"https://github.com/hexgrad/kokoro","pushedAt":"2025-08-06T22:28:53Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/hexgrad/kokoro/main/README.md","observedAt":"2026-09-03T16:10:14.860Z","sha256":"b50b84220668f8247a2405b249c34c7083acc24114279ff1429fd79f46a2c04b"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"hexgrad/kokoro:metadata","source_url":"https://github.com/hexgrad/kokoro","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3ABlaizzy%2Fmlx-video%20repo%3Aopenai%2Fwhisper%20repo%3Am-bain%2FwhisperX%20repo%3ASYSTRAN%2Ffaster-whisper%20repo%3Aggml-org%2Fwhisper.cpp%20repo%3AFunAudioLLM%2FCosyVoice%20repo%3ASWivid%2FF5-TTS%20repo%3Ahexgrad%2Fkokoro&per_page=100","stars":8674,"forks":948,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:35.124Z"},{"source_type":"github","source_identifier":"hexgrad/kokoro:readme:b50b84220668f8247a2405b249c34c7083acc24114279ff1429fd79f46a2c04b","source_url":"https://raw.githubusercontent.com/hexgrad/kokoro/main/README.md","raw_metadata":{"sha256":"b50b84220668f8247a2405b249c34c7083acc24114279ff1429fd79f46a2c04b","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:14.860Z"}],"expected":null},{"identity":"repo:https://github.com/automatic1111/stable-diffusion-webui","slug":"stable-diffusion-webui-51af70fe","name":"Stable Diffusion WebUI","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một bàn điều khiển để tạo, sửa vùng và thử nhiều biến thể hình AI.","description":"Stable Diffusion WebUI của AUTOMATIC1111 đưa các thao tác tạo hình vào giao diện Gradio. Điểm hữu ích là lưu thông số cùng ảnh và so sánh biến thể có hệ thống, thay vì tạo nhiều ảnh rồi mất dấu cách tái tạo. Đây là nền tảng, không bao gồm quyền sử dụng mọi checkpoint cộng đồng.","long_description":"ĐIỂM NỔI BẬT\n• Text-to-image, image-to-image, inpainting và outpainting.\n• Lưu/khôi phục tham số từ ảnh, so sánh cấu hình bằng X/Y/Z plot.\n• Có LoRA, upscaling, batch và hệ extension.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử vài bố cục thumbnail trên cùng brief, lưu seed và thông số cho phương án đã chọn.\n\nBẮT ĐẦU\nTheo hướng dẫn hệ điều hành/GPU chính chủ, chọn checkpoint có nguồn và giấy phép rõ ràng.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nExtension là code có thể chạy trên máy; không cài hàng loạt hoặc bật chạy code tùy ý. Một số hướng dẫn phụ thuộc phiên bản cũ; kiểm tra tính tương thích trước.","canonical_url":"https://github.com/AUTOMATIC1111/stable-diffusion-webui","repository_url":"https://github.com/AUTOMATIC1111/stable-diffusion-webui","documentation_url":"https://raw.githubusercontent.com/AUTOMATIC1111/stable-diffusion-webui/master/README.md","owner_name":"AUTOMATIC1111","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":56,"categories":["image","design"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Một bàn điều khiển để tạo, sửa vùng và thử nhiều biến thể hình AI. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một bàn điều khiển để tạo, sửa vùng và thử nhiều biến thể hình AI.","highlights":["Text-to-image, image-to-image, inpainting và outpainting.","Lưu/khôi phục tham số từ ảnh, so sánh cấu hình bằng X/Y/Z plot.","Có LoRA, upscaling, batch và hệ extension."],"example":"Thử vài bố cục thumbnail trên cùng brief, lưu seed và thông số cho phương án đã chọn.","setup":"Theo hướng dẫn hệ điều hành/GPU chính chủ, chọn checkpoint có nguồn và giấy phép rõ ràng.","limitations":"Extension là code có thể chạy trên máy; không cài hàng loạt hoặc bật chạy code tùy ý. Một số hướng dẫn phụ thuộc phiên bản cũ; kiểm tra tính tương thích trước.","github":{"stars":164783,"forks":30556,"observedAt":"2026-09-03T16:08:48.098Z","url":"https://github.com/AUTOMATIC1111/stable-diffusion-webui","pushedAt":"2026-03-02T07:00:53Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/AUTOMATIC1111/stable-diffusion-webui/master/README.md","observedAt":"2026-09-03T16:10:22.402Z","sha256":"bd853b26858ab8f5065d2e6b90b3552ff8f169977140f3b77a96ed1753bfe916"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"AUTOMATIC1111/stable-diffusion-webui:metadata","source_url":"https://github.com/AUTOMATIC1111/stable-diffusion-webui","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aace-step%2FACE-Step-1.5%20repo%3Afacebookresearch%2Faudiocraft%20repo%3AAnjok07%2Fultimatevocalremovergui%20repo%3Aaudacity%2Faudacity%20repo%3AComfy-Org%2FComfyUI%20repo%3AAUTOMATIC1111%2Fstable-diffusion-webui%20repo%3Alllyasviel%2FFooocus%20repo%3Ainvoke-ai%2FInvokeAI&per_page=100","stars":164783,"forks":30556,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:08:48.098Z"},{"source_type":"github","source_identifier":"AUTOMATIC1111/stable-diffusion-webui:readme:bd853b26858ab8f5065d2e6b90b3552ff8f169977140f3b77a96ed1753bfe916","source_url":"https://raw.githubusercontent.com/AUTOMATIC1111/stable-diffusion-webui/master/README.md","raw_metadata":{"sha256":"bd853b26858ab8f5065d2e6b90b3552ff8f169977140f3b77a96ed1753bfe916","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:22.402Z"}],"expected":null},{"identity":"repo:https://github.com/lllyasviel/fooocus","slug":"fooocus-59a8a41e","name":"Fooocus","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tập trung vào prompt và ảnh, giảm số thông số phải chỉnh khi bắt đầu với SDXL.","description":"Fooocus là giao diện tạo ảnh offline dựa trên SDXL, có biến thể, nâng cỡ và chỉnh vùng. Nó phù hợp người muốn thử một bộ công cụ tương đối tập trung. Tuy nhiên, chính chủ đã chuyển sang hỗ trợ dài hạn hạn chế, chỉ sửa lỗi, chưa có kế hoạch tích hợp kiến trúc model mới.","long_description":"ĐIỂM NỔI BẬT\n• Tạo ảnh từ prompt với style và cấu hình mặc định.\n• Biến thể nhẹ/mạnh, upscale, inpaint/outpaint.\n• Có ảnh tham chiếu và lựa chọn tỉ lệ khung hình.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTạo vài phương án hình minh họa SDXL, chọn ảnh rồi chỉnh một vùng nhỏ thay vì sinh lại toàn bộ.\n\nBẮT ĐẦU\nChỉ lấy từ repo chính chủ và liên kết tải trong đó; kiểm tra GPU và dung lượng trống.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nLTS, không giới thiệu là nơi thử model mới nhất. Tác giả cảnh báo nhiều website giả mạo Fooocus; model và tài nguyên thêm có giấy phép riêng.","canonical_url":"https://github.com/lllyasviel/Fooocus","repository_url":"https://github.com/lllyasviel/Fooocus","documentation_url":"https://raw.githubusercontent.com/lllyasviel/Fooocus/main/readme.md","owner_name":"lllyasviel","license":"GPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":57,"categories":["image","design"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Tập trung vào prompt và ảnh, giảm số thông số phải chỉnh khi bắt đầu với SDXL. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tập trung vào prompt và ảnh, giảm số thông số phải chỉnh khi bắt đầu với SDXL.","highlights":["Tạo ảnh từ prompt với style và cấu hình mặc định.","Biến thể nhẹ/mạnh, upscale, inpaint/outpaint.","Có ảnh tham chiếu và lựa chọn tỉ lệ khung hình."],"example":"Tạo vài phương án hình minh họa SDXL, chọn ảnh rồi chỉnh một vùng nhỏ thay vì sinh lại toàn bộ.","setup":"Chỉ lấy từ repo chính chủ và liên kết tải trong đó; kiểm tra GPU và dung lượng trống.","limitations":"LTS, không giới thiệu là nơi thử model mới nhất. Tác giả cảnh báo nhiều website giả mạo Fooocus; model và tài nguyên thêm có giấy phép riêng.","github":{"stars":52723,"forks":8595,"observedAt":"2026-09-03T16:08:48.098Z","url":"https://github.com/lllyasviel/Fooocus","pushedAt":"2025-12-01T19:17:07Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/lllyasviel/Fooocus/main/readme.md","observedAt":"2026-09-03T16:10:24.751Z","sha256":"89e1efb0ef1245a6b2abc4db41d5b76e3179656f875db99675900dc477e067bf"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"lllyasviel/Fooocus:metadata","source_url":"https://github.com/lllyasviel/Fooocus","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aace-step%2FACE-Step-1.5%20repo%3Afacebookresearch%2Faudiocraft%20repo%3AAnjok07%2Fultimatevocalremovergui%20repo%3Aaudacity%2Faudacity%20repo%3AComfy-Org%2FComfyUI%20repo%3AAUTOMATIC1111%2Fstable-diffusion-webui%20repo%3Alllyasviel%2FFooocus%20repo%3Ainvoke-ai%2FInvokeAI&per_page=100","stars":52723,"forks":8595,"license":"GPL-3.0"},"fetched_at":"2026-09-03T16:08:48.098Z"},{"source_type":"github","source_identifier":"lllyasviel/Fooocus:readme:89e1efb0ef1245a6b2abc4db41d5b76e3179656f875db99675900dc477e067bf","source_url":"https://raw.githubusercontent.com/lllyasviel/Fooocus/main/readme.md","raw_metadata":{"sha256":"89e1efb0ef1245a6b2abc4db41d5b76e3179656f875db99675900dc477e067bf","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:24.751Z"}],"expected":null},{"identity":"repo:https://github.com/upscayl/upscayl","slug":"upscayl-7851dfb1","name":"Upscayl","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Phóng lớn ảnh nhỏ bằng giao diện đơn giản trước khi đưa vào thiết kế.","description":"Upscayl là ứng dụng nâng độ phân giải bằng AI trên desktop. Thích hợp người muốn xử lý ảnh mà không tự viết script, có lựa chọn model và xử lý theo lô. Chính FAQ giải thích AI đoán chi tiết, chứ không khôi phục chắc chắn thông tin vốn không có.","long_description":"ĐIỂM NỔI BẬT\n• Ứng dụng Windows, macOS và Linux.\n• Nâng cỡ ảnh với model AI và batch.\n• Có gallery trước/sau và tài liệu tương thích phần cứng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTăng kích thước hình minh họa bạn có quyền dùng, kiểm tra nét chữ và cạnh trước khi đặt lên carousel.\n\nBẮT ĐẦU\nTải bản desktop chính chủ; kiểm tra GPU hỗ trợ Vulkan.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông phù hợp cứu mọi ảnh mất nét hoặc out-of-focus. Nhiều GPU tích hợp/CPU không được hỗ trợ; chi tiết do AI tạo không nên được coi là bằng chứng gốc.","canonical_url":"https://github.com/upscayl/upscayl","repository_url":"https://github.com/upscayl/upscayl","documentation_url":"https://raw.githubusercontent.com/upscayl/upscayl/main/README.md","owner_name":"upscayl","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":58,"categories":["image","design"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Phóng lớn ảnh nhỏ bằng giao diện đơn giản trước khi đưa vào thiết kế. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Phóng lớn ảnh nhỏ bằng giao diện đơn giản trước khi đưa vào thiết kế.","highlights":["Ứng dụng Windows, macOS và Linux.","Nâng cỡ ảnh với model AI và batch.","Có gallery trước/sau và tài liệu tương thích phần cứng."],"example":"Tăng kích thước hình minh họa bạn có quyền dùng, kiểm tra nét chữ và cạnh trước khi đặt lên carousel.","setup":"Tải bản desktop chính chủ; kiểm tra GPU hỗ trợ Vulkan.","limitations":"Không phù hợp cứu mọi ảnh mất nét hoặc out-of-focus. Nhiều GPU tích hợp/CPU không được hỗ trợ; chi tiết do AI tạo không nên được coi là bằng chứng gốc.","github":{"stars":48966,"forks":2457,"observedAt":"2026-09-03T16:08:54.574Z","url":"https://github.com/upscayl/upscayl","pushedAt":"2026-08-20T01:28:53Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/upscayl/upscayl/main/README.md","observedAt":"2026-09-03T16:10:29.617Z","sha256":"4f3467e3748517bd6bf67d8c412e24a1de461e7642d2a4d83e6cd3e082ebb8d0"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"upscayl/upscayl:metadata","source_url":"https://github.com/upscayl/upscayl","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AAcly%2Fkrita-ai-diffusion%20repo%3ASanster%2FIOPaint%20repo%3Aupscayl%2Fupscayl%20repo%3Axinntao%2FReal-ESRGAN%20repo%3AQwenLM%2FQwen-Image%20repo%3Ablack-forest-labs%2Fflux%20repo%3ATencent-Hunyuan%2FHunyuan3D-2