ries":["image","video"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Thêm bước phục hồi và nâng cỡ hình vào một pipeline có thể chạy lặp lại. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Thêm bước phục hồi và nâng cỡ hình vào một pipeline có thể chạy lặp lại.","highlights":["Nhiều model theo loại nội dung và mức xử lý.","Có xử lý theo tile, kênh alpha và lựa chọn mức khử nhiễu.","Có script Python và binary NCNN được repo dẫn, không bắt buộc cùng môi trường CUDA."],"example":"Thử một vài frame minh họa trước, so chi tiết giả và độ nhất quán rồi mới quyết định xử lý cả bộ.","setup":"Chọn model đúng loại hình và cách dùng Python/binary theo tài liệu.","limitations":"Nâng cỡ có thể làm mịn quá hoặc thêm chi tiết sai. Tham số scale tùy ý có thể gồm bước resize bổ sung, không đồng nghĩa mọi tỉ lệ đều do AI tái tạo nguyên bản.","github":{"stars":36677,"forks":4458,"observedAt":"2026-09-03T16:08:54.574Z","url":"https://github.com/xinntao/Real-ESRGAN","pushedAt":"2024-08-06T13:15:18Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/xinntao/Real-ESRGAN/master/README.md","observedAt":"2026-09-03T16:10:29.983Z","sha256":"d0a13607913ea94e65a91ac864b969683a41a45b0aec16e0ae64271649d0364d"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"xinntao/Real-ESRGAN:metadata","source_url":"https://github.com/xinntao/Real-ESRGAN","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AAcly%2Fkrita-ai-diffusion%20repo%3ASanster%2FIOPaint%20repo%3Aupscayl%2Fupscayl%20repo%3Axinntao%2FReal-ESRGAN%20repo%3AQwenLM%2FQwen-Image%20repo%3Ablack-forest-labs%2Fflux%20repo%3ATencent-Hunyuan%2FHunyuan3D-2%20repo%3Amicrosoft%2FTRELLIS&per_page=100","stars":36677,"forks":4458,"license":"BSD-3-Clause"},"fetched_at":"2026-09-03T16:08:54.574Z"},{"source_type":"github","source_identifier":"xinntao/Real-ESRGAN:readme:d0a13607913ea94e65a91ac864b969683a41a45b0aec16e0ae64271649d0364d","source_url":"https://raw.githubusercontent.com/xinntao/Real-ESRGAN/master/README.md","raw_metadata":{"sha256":"d0a13607913ea94e65a91ac864b969683a41a45b0aec16e0ae64271649d0364d","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:29.983Z"}],"expected":null},{"identity":"repo:https://github.com/invoke-ai/invokeai","slug":"invokeai-c34bf9c2","name":"InvokeAI","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tạo hình như một quá trình chỉnh sửa trên canvas, không chỉ một ô prompt.","description":"InvokeAI kết hợp canvas, công cụ vẽ/chọn vùng, workflow node và quản lý hình trong một không gian làm việc. Nó hợp creator cần tiếp tục sửa một visual đã gần đúng, đồng thời giữ lịch sử prompt và tổ chức các phương án của dự án.","long_description":"ĐIỂM NỔI BẬT\n• Unified Canvas có in/out-painting và brush.\n• Quản lý và chia sẻ pipeline dựa trên node.\n• Board/gallery lưu hình, metadata và các lựa chọn model.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nSửa nền của ảnh chiến dịch, giữ vùng chủ thể rồi lưu các phương án trong cùng board để so sánh.\n\nBẮT ĐẦU\nDùng Launcher từ nguồn chính chủ, kiểm tra phần cứng và chọn model phù hợp.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nDanh sách hỗ trợ có model chỉ dùng qua API; không coi tất cả đều chạy local miễn phí. Quyền model, ảnh tham chiếu và dịch vụ ngoài phải kiểm tra riêng.","canonical_url":"https://github.com/invoke-ai/InvokeAI","repository_url":"https://github.com/invoke-ai/InvokeAI","documentation_url":"https://raw.githubusercontent.com/invoke-ai/InvokeAI/main/README.md","owner_name":"invoke-ai","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":60,"categories":["image","design"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Tạo hình như một quá trình chỉnh sửa trên canvas, không chỉ một ô prompt. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tạo hình như một quá trình chỉnh sửa trên canvas, không chỉ một ô prompt.","highlights":["Unified Canvas có in/out-painting và brush.","Quản lý và chia sẻ pipeline dựa trên node.","Board/gallery lưu hình, metadata và các lựa chọn model."],"example":"Sửa nền của ảnh chiến dịch, giữ vùng chủ thể rồi lưu các phương án trong cùng board để so sánh.","setup":"Dùng Launcher từ nguồn chính chủ, kiểm tra phần cứng và chọn model phù hợp.","limitations":"Danh sách hỗ trợ có model chỉ dùng qua API; không coi tất cả đều chạy local miễn phí. Quyền model, ảnh tham chiếu và dịch vụ ngoài phải kiểm tra riêng.","github":{"stars":28123,"forks":2968,"observedAt":"2026-09-03T16:08:48.098Z","url":"https://github.com/invoke-ai/InvokeAI","pushedAt":"2026-09-01T00:42:16Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/invoke-ai/InvokeAI/main/README.md","observedAt":"2026-09-03T16:10:25.413Z","sha256":"48293a6dbe76e2980f0532b64ee8bd2e236d48ff00c8601bc35c9e0bdf80646a"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"invoke-ai/InvokeAI:metadata","source_url":"https://github.com/invoke-ai/InvokeAI","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aace-step%2FACE-Step-1.5%20repo%3Afacebookresearch%2Faudiocraft%20repo%3AAnjok07%2Fultimatevocalremovergui%20repo%3Aaudacity%2Faudacity%20repo%3AComfy-Org%2FComfyUI%20repo%3AAUTOMATIC1111%2Fstable-diffusion-webui%20repo%3Alllyasviel%2FFooocus%20repo%3Ainvoke-ai%2FInvokeAI&per_page=100","stars":28123,"forks":2968,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:48.098Z"},{"source_type":"github","source_identifier":"invoke-ai/InvokeAI:readme:48293a6dbe76e2980f0532b64ee8bd2e236d48ff00c8601bc35c9e0bdf80646a","source_url":"https://raw.githubusercontent.com/invoke-ai/InvokeAI/main/README.md","raw_metadata":{"sha256":"48293a6dbe76e2980f0532b64ee8bd2e236d48ff00c8601bc35c9e0bdf80646a","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:25.413Z"}],"expected":null}]'::jsonb) loop
  select * into existing from public.resources where external_identity=x->>'identity' for update;
  already:=found and existing.import_metadata->>'creatorImportHash'='70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf';
  if already then continue; end if;
  if existing.id is not null and (existing.id::text is distinct from x->>'expected' or existing.editorial_revision<>0 or existing.status<>'CANDIDATE') then raise exception 'Candidate changed since snapshot: %',x->>'identity'; end if;
  if existing.id is null and x->>'expected' is not null then raise exception 'Candidate disappeared since snapshot'; end if;
  if existing.id is null then
    insert into public.resources(external_identity,slug,type,name,canonical_url) values(x->>'identity',x->>'slug',(x->>'type')::public.resource_type,x->>'name',x->>'canonical_url') returning id into rid;
  else rid:=existing.id; end if;
  update public.resources set name=x->>'name',type=(x->>'type')::public.resource_type,tagline=x->>'tagline',description=x->>'description',long_description=x->>'long_description',canonical_url=x->>'canonical_url',repository_url=x->>'repository_url',documentation_url=x->>'documentation_url',owner_name=x->>'owner_name',license=x->>'license',import_metadata=import_metadata||(x->'import_metadata')||jsonb_build_object('creatorImportHash','70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf'),last_source_update_at=(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz,editorial_revision=editorial_revision+1,updated_at=now() where id=rid;
  for s in select value from jsonb_array_elements(x->'sources') loop
    insert into public.resource_sources(resource_id,source_type,source_identifier,source_url,raw_metadata,fetched_at) values(rid,s->>'source_type',s->>'source_identifier',s->>'source_url',s->'raw_metadata',(s->>'fetched_at')::timestamptz) on conflict(resource_id,source_type,source_identifier) do update set source_url=excluded.source_url,raw_metadata=excluded.raw_metadata,fetched_at=excluded.fetched_at;
  end loop;
  insert into public.resource_metric_snapshots(resource_id,source_type,metric_key,metric_value,captured_at) values(rid,'github','stars',(x#>>'{import_metadata,creatorCatalog,github,stars}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz),(rid,'github','forks',(x#>>'{import_metadata,creatorCatalog,github,forks}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz) on conflict do nothing;
  insert into public.resource_evidence_jobs(resource_id) values(rid) on conflict do nothing;
end loop;
end $creator_import$;
